23	export async function api(path, { method = "GET", body } = {}) {
24	  const headers = {};
25	  if (body !== undefined) headers["Content-Type"] = "application/json";
26	  const code = getAccessCode();
27	  if (code) headers["X-Demo-Access-Code"] = code;
28	  const response = await fetch(`/api${path}`, {
29	    method,
30	    headers,
31	    body: body === undefined ? undefined : JSON.stringify(body),
32	  });
33	  let payload = null;
34	  try {
35	    payload = await response.json();
36	  } catch {
37	    // A response without a JSON body; the status code carries the outcome.
38	  }
39	  if (!response.ok) {
40	    const detail = payload?.detail;
41	    const message = Array.isArray(detail)
42	      ? detail.map((d) => `${d.loc?.slice(1).join(".")}: ${d.msg}`).join("; ")
43	      : detail || `${response.status} ${response.statusText}`;
44	    const error = new Error(message);
45	    error.status = response.status;
46	    throw error;
47	  }
48	  return payload;
49	}
