51	// Poll `path` every `intervalMs`. Keeps the last good data while a refresh is
52	// in flight or failing, so the page never flashes empty.
53	export function usePoll(path, intervalMs = 2500) {
54	  const [data, setData] = useState(null);
55	  const [error, setError] = useState(null);
56	  const latest = useRef(path);
57	  latest.current = path;
58	
59	  const refresh = useCallback(async () => {
60	    if (!path) return;
61	    try {
62	      const next = await api(path);
63	      if (latest.current === path) {
64	        setData(next);
65	        setError(null);
66	      }
67	    } catch (err) {
68	      if (latest.current === path) setError(err);
69	    }
70	  }, [path]);
71	
72	  useEffect(() => {
73	    setData(null);
74	    setError(null);
75	    if (!path) return undefined;
76	    refresh();
77	    const timer = window.setInterval(refresh, intervalMs);
78	    return () => window.clearInterval(timer);
79	  }, [path, intervalMs, refresh]);
80	
81	  return { data, error, refresh };
82	}
