84	// Run a mutating call and expose its busy and error state to a button.
85	export function useAction() {
86	  const [busy, setBusy] = useState(false);
87	  const [error, setError] = useState(null);
88	  const run = useCallback(async (fn) => {
89	    setBusy(true);
90	    setError(null);
91	    try {
92	      return await fn();
93	    } catch (err) {
94	      setError(err.message);
95	      return undefined;
96	    } finally {
97	      setBusy(false);
98	    }
99	  }, []);
100	  return { busy, error, run, clearError: () => setError(null) };
101	}
